   149	function isFirstLetterEmoji(message: string): boolean {
   150	    const trimmedMessage = Str.replaceAll(message.replace(/ /g, ''), '\n', '');
   151	    const match = trimmedMessage.match(CONST.REGEX.EMOJIS);
   152	
   153	    if (!match) {
   154	        return false;
   155	    }
   156	
   157	    return trimmedMessage.startsWith(match[0]);
   158	}
