   160	/**
   161	 * Validates that this message contains only emojis
   162	 */
   163	function containsOnlyEmojis(message: string): boolean {
   164	    const trimmedMessage = Str.replaceAll(message.replace(/ /g, ''), '\n', '');
   165	    const match = trimmedMessage.match(CONST.REGEX.EMOJIS);
   166	
   167	    if (!match) {
   168	        return false;
   169	    }
   170	
   171	    const codes = [];
   172	    match.map((emoji) =>
   173	        getEmojiUnicode(emoji)
   174	            .split(' ')
   175	            .map((code) => {
   176	                if (!(CONST.INVISIBLE_CODEPOINTS as readonly string[]).includes(code)) {
   177	                    codes.push(code);
   178	                }
   179	                return code;
   180	            }),
   181	    );
   182	
   183	    // Emojis are stored as multiple characters, so we're using spread operator
   184	    // to iterate over the actual emojis, not just characters that compose them
   185	    const messageCodes = [...trimmedMessage]
   186	        .map((char) => getEmojiUnicode(char))
   187	        .filter((string) => string.length > 0 && !(CONST.INVISIBLE_CODEPOINTS as readonly string[]).includes(string));
   188	    return codes.length === messageCodes.length;
   189	}
