   193	 */
   194	function getHeaderEmojis(emojis: EmojiPickerList): HeaderIndice[] {
   195	    const headerIndices: HeaderIndice[] = [];
   196	    emojis.forEach((emoji, index) => {
   197	        if (!('header' in emoji)) {
