   205	/**
   206	 * Get number of empty spaces to be filled to get equal emojis for every row
   207	 */
   208	function getDynamicSpacing(emojiCount: number, suffix: number): EmojiSpacer[] {
   209	    const spacerEmojis = [];
   210	    let modLength = CONST.EMOJI_NUM_PER_ROW - (emojiCount % CONST.EMOJI_NUM_PER_ROW);
   211	
   212	    // Empty spaces is pushed if the given row has less than eight emojis
   213	    while (modLength > 0 && modLength < CONST.EMOJI_NUM_PER_ROW) {
   214	        spacerEmojis.push({
   215	            code: `${CONST.EMOJI_SPACER}_${suffix}_${modLength}`,
   216	            spacer: true,
   217	        });
   218	        modLength -= 1;
   219	    }
   220	    return spacerEmojis;
   221	}
