   223	/**
   224	 * Add dynamic spaces to emoji categories
   225	 */
   226	function addSpacesToEmojiCategories(emojis: PickerEmojis): EmojiPickerList {
   227	    let updatedEmojis: EmojiPickerList = [];
   228	    emojis.forEach((emoji, index) => {
   229	        if (emoji && typeof emoji === 'object' && 'header' in emoji) {
   230	            updatedEmojis = updatedEmojis.concat(getDynamicSpacing(updatedEmojis.length, index), [emoji], getDynamicSpacing(1, index));
