   262	
   263	/**
   264	 * Given an emoji item object, return an emoji code based on its type.
   265	 */
   266	const getEmojiCodeWithSkinColor = (item: Emoji, preferredSkinToneIndex: OnyxEntry<number | string>): string => {
   267	    const {code, types} = item;
   268	
   269	    if (typeof preferredSkinToneIndex === 'number' && types?.[preferredSkinToneIndex]) {
   270	        return types[preferredSkinToneIndex];
   271	    }
   272	
   273	    return code;
   274	};
