   276	/**
   277	 * Extracts emojis from a given text.
   278	 *
   279	 * @param text - The text to extract emojis from.
   280	 * @returns An array of emoji codes.
   281	 */
   282	function extractEmojis(text: string): Emoji[] {
   283	    if (!text) {
   284	        return [];
   285	    }
   286	
   287	    // Parse Emojis including skin tones - Eg: ['👩🏻', '👩🏻', '👩🏼', '👩🏻', '👩🏼', '👩']
   288	    const parsedEmojis = text.match(CONST.REGEX.EMOJIS);
   289	
   290	    if (!parsedEmojis) {
   291	        return [];
   292	    }
   293	
   294	    const emojis: Emoji[] = [];
   295	
   296	    // Text can contain similar emojis as well as their skin tone variants. Create a Set to remove duplicate emojis from the search.
   297	
   298	    for (const character of parsedEmojis) {
   299	        const emoji = Emojis.emojiCodeTableWithSkinTones[character];
   300	        if (emoji) {
   301	            emojis.push(emoji);
   302	        }
   303	    }
   304	
   305	    return emojis;
   306	}
