   308	/**
   309	 * Take the current emojis and the former emojis and return the emojis that were added, if we add an already existing emoji, we also return it
   310	 * @param currentEmojis The array of current emojis
   311	 * @param formerEmojis The array of former emojis
   312	 * @returns The array of added emojis
   313	 */
   314	function getAddedEmojis(currentEmojis: Emoji[], formerEmojis: Emoji[]): Emoji[] {
   315	    const newEmojis: Emoji[] = [...currentEmojis];
   316	    // We are removing the emojis from the newEmojis array if they were already present before.
   317	    formerEmojis.forEach((formerEmoji) => {
   318	        const indexOfAlreadyPresentEmoji = newEmojis.findIndex((newEmoji) => newEmoji.code === formerEmoji.code);
   319	        if (indexOfAlreadyPresentEmoji >= 0) {
   320	            newEmojis.splice(indexOfAlreadyPresentEmoji, 1);
   321	        }
   322	    });
   323	    return newEmojis;
   324	}
