   326	/**
   327	 * Replace any emoji name in a text with the emoji icon.
   328	 * If we're on mobile, we also add a space after the emoji granted there's no text after it.
   329	 */
   330	function replaceEmojis(text: string, preferredSkinTone: OnyxEntry<number | string> = CONST.EMOJI_DEFAULT_SKIN_TONE, lang: Locale = CONST.LOCALES.DEFAULT): ReplacedEmoji {
   331	    // emojisTrie is importing the emoji JSON file on the app starting and we want to avoid it
   332	    const emojisTrie = require<EmojiTrieModule>('./EmojiTrie').default;
   333	
   334	    const trie = emojisTrie[lang as SupportedLanguage];
   335	    if (!trie) {
   336	        return {text, emojis: []};
   337	    }
   338	
   339	    let newText = text;
   340	    const emojis: Emoji[] = [];
   341	    const emojiData = text.match(CONST.REGEX.EMOJI_NAME);
   342	    if (!emojiData || emojiData.length === 0) {
   343	        return {text: newText, emojis};
   344	    }
   345	
   346	    let cursorPosition;
   347	
   348	    for (const emoji of emojiData) {
   349	        const name = emoji.slice(1, -1);
   350	        let checkEmoji = trie.search(name);
   351	        // If the user has selected a language other than English, and the emoji doesn't exist in that language,
   352	        // we will check if the emoji exists in English.
   353	        if (lang !== CONST.LOCALES.DEFAULT && !checkEmoji?.metaData?.code) {
   354	            const englishTrie = emojisTrie[CONST.LOCALES.DEFAULT];
   355	            if (englishTrie) {
   356	                const englishEmoji = englishTrie.search(name);
   357	                checkEmoji = englishEmoji;
   358	            }
   359	        }
   360	        if (checkEmoji?.metaData?.code && checkEmoji?.metaData?.name) {
   361	            const emojiReplacement = getEmojiCodeWithSkinColor(checkEmoji.metaData as Emoji, preferredSkinTone);
   362	            emojis.push({
   363	                name,
   364	                code: checkEmoji.metaData?.code,
   365	                types: checkEmoji.metaData.types,
   366	            });
   367	
   368	            // Set the cursor to the end of the last replaced Emoji. Note that we position after
   369	            // the extra space, if we added one.
   370	            cursorPosition = newText.indexOf(emoji) + (emojiReplacement?.length ?? 0);
   371	
   372	            newText = newText.replace(emoji, emojiReplacement ?? '');
   373	        }
   374	    }
