   376	    // cursorPosition, when not undefined, points to the end of the last emoji that was replaced.
   377	    // In that case we want to append a space at the cursor position, but only if the next character
   378	    // is not already a space (to avoid double spaces).
   379	    if (cursorPosition && cursorPosition > 0) {
   380	        const space = ' ';
   381	
   382	        if (newText.charAt(cursorPosition) !== space) {
   383	            newText = newText.slice(0, cursorPosition) + space + newText.slice(cursorPosition);
   384	        }
   385	        cursorPosition += space.length;
   386	    }
   387	
   388	    return {text: newText, emojis, cursorPosition};
   389	}
