   391	/**
   392	 * Find all emojis in a text and replace them with their code.
   393	 */
   394	function replaceAndExtractEmojis(text: string, preferredSkinTone: OnyxEntry<number | string> = CONST.EMOJI_DEFAULT_SKIN_TONE, lang: Locale = CONST.LOCALES.DEFAULT): ReplacedEmoji {
   395	    const {text: convertedText = '', emojis = [], cursorPosition} = replaceEmojis(text, preferredSkinTone, lang);
   396	
   397	    return {
   398	        text: convertedText,
   399	        emojis: emojis.concat(extractEmojis(text)),
